func localizedLabels(labelDE string, labels map[string]string) LocalizedString {
	out := make(LocalizedString, len(labels)+1)
	for key, value := range labels {
		if value != "" {
			out[key] = value
		}
	}
	if out["de"] == "" {
		out["de"] = labelDE
	}
	return out
}

// LookupAttribute returns the Attribute with the given key, or false if not found.
func LookupAttribute(key string) (Attribute, bool) {
	return lookupAttribute(Schema.Attributes, key)
}

func lookupAttribute(attrs []Attribute, key string) (Attribute, bool) {
	for _, a := range attrs {
		if a.Key == key {
			return a, true
		}
		if found, ok := lookupAttribute(a.Subfields, key); ok {
			return found, ok
		}
	}
	return Attribute{}, false
}

